<?php
// backend/migrations/migrate_lecturers_from_excel.php
require_once __DIR__ . '/../db_connect.php';

echo "=== MIGRATING LECTURERS FROM EXCEL INTO COMPANIES TABLE ===\n\n";

$data = json_decode(base64_decode(''), true);

if (!is_array($data)) {
    die("ERROR: Invalid payload json\n");
}

$inserted = 0;
$updated = 0;
$skipped = 0;

$adminUserId = 100059; // Hoang Phuc
$tenantId = 1;

foreach ($data as $idx => $item) {
    $name = trim($item['name'] ?? '');
    if (!$name) continue;

    $phone = trim($item['phone'] ?? '');
    $email = trim($item['email'] ?? '');
    $address = trim($item['address'] ?? '');
    $country = trim($item['country'] ?? 'Việt Nam');
    $bankName = trim($item['bank_name'] ?? '');
    $bankAccNum = trim($item['bank_account_number'] ?? '');
    $bankAccName = trim($item['bank_account_name'] ?? '');
    $tier = 'giang_vien';
    $industry = 'Giảng viên';
    $tagsJson = json_encode($item['tags'] ?? ['giang_vien'], JSON_UNESCAPED_UNICODE);
    $notes = trim($item['notes'] ?? '');
    $status = 'active';

    // Check if lecturer exists by name or phone or email
    $existing = null;

    // 1. Check by exact name
    $stmt = $conn->prepare("SELECT id, name, tags, notes, bank_name, bank_account_number, bank_account_name FROM companies WHERE name = ? LIMIT 1");
    $stmt->bind_param("s", $name);
    $stmt->execute();
    $res = $stmt->get_result();
    if ($res && $res->num_rows > 0) {
        $existing = $res->fetch_assoc();
    }
    $stmt->close();

    // 2. If not found, check by email if valid
    if (!$existing && $email && strpos($email, '@') !== false) {
        $firstEmail = trim(explode(',', $email)[0]);
        $stmt = $conn->prepare("SELECT id, name, tags, notes, bank_name, bank_account_number, bank_account_name FROM companies WHERE email LIKE CONCAT('%', ?, '%') LIMIT 1");
        $stmt->bind_param("s", $firstEmail);
        $stmt->execute();
        $res = $stmt->get_result();
        if ($res && $res->num_rows > 0) {
            $existing = $res->fetch_assoc();
        }
        $stmt->close();
    }

    // 3. If not found, check by phone
    if (!$existing && $phone && strlen(preg_replace('/\D/', '', $phone)) >= 9) {
        $cleanP = preg_replace('/\D/', '', $phone);
        $stmt = $conn->prepare("SELECT id, name, tags, notes, bank_name, bank_account_number, bank_account_name FROM companies WHERE REPLACE(REPLACE(phone, ' ', ''), '-', '') LIKE CONCAT('%', ?, '%') LIMIT 1");
        $stmt->bind_param("s", $cleanP);
        $stmt->execute();
        $res = $stmt->get_result();
        if ($res && $res->num_rows > 0) {
            $existing = $res->fetch_assoc();
        }
        $stmt->close();
    }

    if ($existing) {
        $existId = (int)$existing['id'];
        echo "[" . ($idx + 1) . "] Updating existing lecturer ID {$existId}: '{$name}'...\n";

        // Merge tags
        $existTags = [];
        if (!empty($existing['tags'])) {
            $dec = json_decode($existing['tags'], true);
            if (is_array($dec)) $existTags = $dec;
        }
        $newTags = array_values(array_unique(array_merge($existTags, $item['tags'] ?? ['giang_vien'])));
        $mergedTagsJson = json_encode($newTags, JSON_UNESCAPED_UNICODE);

        // Update fields if empty in existing
        $updateBankName = !empty($existing['bank_name']) ? $existing['bank_name'] : $bankName;
        $updateBankNum = !empty($existing['bank_account_number']) ? $existing['bank_account_number'] : $bankAccNum;
        $updateBankAccName = !empty($existing['bank_account_name']) ? $existing['bank_account_name'] : $bankAccName;
        $updateNotes = !empty($existing['notes']) ? ($existing['notes'] . "\n---\n" . $notes) : $notes;

        $upStmt = $conn->prepare("UPDATE companies SET tier = 'giang_vien', industry = 'Giảng viên', status = 'active', tags = ?, notes = ?, bank_name = ?, bank_account_number = ?, bank_account_name = ? WHERE id = ?");
        $upStmt->bind_param("sssssi", $mergedTagsJson, $updateNotes, $updateBankName, $updateBankNum, $updateBankAccName, $existId);
        $upStmt->execute();
        $upStmt->close();

        $updated++;
    } else {
        echo "[" . ($idx + 1) . "] Inserting new lecturer: '{$name}'...\n";
        $insStmt = $conn->prepare("INSERT INTO companies (tenant_id, created_by, owner_id, name, phone, email, address, country, bank_name, bank_account_number, bank_account_name, tier, industry, status, tags, notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        $insStmt->bind_param("iiisssssssssssss", $tenantId, $adminUserId, $adminUserId, $name, $phone, $email, $address, $country, $bankName, $bankAccNum, $bankAccName, $tier, $industry, $status, $tagsJson, $notes);
        if ($insStmt->execute()) {
            $newId = $insStmt->insert_id;
            echo "     -> Created company ID: {$newId}\n";
            $inserted++;
        } else {
            echo "     -> ERROR inserting '{$name}': " . $insStmt->error . "\n";
        }
        $insStmt->close();
    }
}

echo "\n=== MIGRATION FINISHED ===\n";
echo "Total processed: " . count($data) . "\n";
echo "Inserted: {$inserted}\n";
echo "Updated: {$updated}\n";
echo "Skipped: {$skipped}\n";
